// Original same-date cash/property ledger; carrier-confirmed inputs, no legal/tax solver.
export const rrifKindDefinitions={rrifKindCash:{title:'Separate a property payment from cash for the next bill',fields:[
 ['rrifKindValue','RRIF value available immediately before the payment (CAD)',400000,0,2000000,10000],
 ['rrifKindPayment','Carrier-confirmed gross payment selected for this illustration (CAD)',25000,0,200000,1000],
 ['rrifKindShare','Share of that payment delivered as securities (%)',60,0,100,5],
 ['rrifKindBank','Accessible bank cash before the payment (CAD)',12000,0,200000,1000],
 ['rrifKindTaxReserve','Separate cash earmark for remaining income tax (CAD)',6000,0,100000,500],
 ['rrifKindSpend','Cash assigned to planned household bills (CAD)',18000,0,200000,1000]
 ]}};
export function rrifKindLedger(i,overrides={}){
 const p={...i,...overrides},paid=Math.min(p.rrifKindPayment,p.rrifKindValue),securities=paid*p.rrifKindShare/100,cash=paid-securities;
 const bankBalance=p.rrifKindBank+cash,budget=bankBalance-p.rrifKindTaxReserve-p.rrifKindSpend;
 return {paid,securities,cash,bankBalance,budget,gap:Math.max(0,-budget),surplus:Math.max(0,budget),unfundedSelectedPayment:p.rrifKindPayment-paid,rrifAfter:p.rrifKindValue-paid};
}
export function rrifKindResult(kind,input){
 if(kind!=='rrifKindCash')throw Error('Unknown RRIF payment illustration');
 const r=rrifKindLedger(input),shares=[...new Set([...Array.from({length:11},(_,n)=>n*10),input.rrifKindShare])].sort((a,b)=>a-b);
 const bankAmounts=[...new Set([0,input.rrifKindBank/2,input.rrifKindBank,input.rrifKindBank*1.5])],matrixShares=[0,25,50,75,100];
 return {metrics:[['Gross payment actually represented',r.paid,'money'],['Cash portion reaching the bank',r.cash,'money'],['Additional cash for the two budget assignments',r.gap,'money']],
 note:'Original hypothetical same-date CAD ledger, assuming a carrier-approved ordinary minimum-payment illustration and a separate non-registered destination for securities. No source deductions, fees, sale, price change, settlement delay or return is modeled. All values use the same assumed transfer-date valuation. The selected gross payment is capped at entered available RRIF value; any unrepresented request is reported separately and is not a finding of a statutory breach. The calculator does not determine the legal minimum, issuer availability, tax liability, contribution room, benefit effects or cost basis. Income-tax cash is an independently entered earmark, not a tax calculation. Both tax and household spending are budget assignments; the displayed bank balance is measured before either is paid. A negative budget remainder is an unfunded assignment, not a negative bank account or automatic loan.',
 charts:[
  {id:'rrif-kind-payment-parts',type:'stackbar',unit:'money',title:'The represented gross payment includes two different forms',unitLabel:'CAD at the same assumed transfer-date value',seriesNames:['Securities received outside the RRIF','Cash received in the bank'],rows:[{label:'Gross payment represented',values:[r.securities,r.cash]}],note:'The two parts sum to the represented payment, not to two separate withdrawals. Securities remain property and are not automatically sold. At the selected inputs, the unrepresented part of the requested payment is CAD '+r.unfundedSelectedPayment.toLocaleString('en-CA',{maximumFractionDigits:2})+'. Confirm the actual payment amount and permissible form with the carrier; this is not a statutory-minimum compliance test.'},
  {id:'rrif-kind-cash-budget',type:'waterfall',unit:'money',title:'Assign the actual bank cash to tax and household bills',unitLabel:'CAD budget capacity; assignments do not represent completed payments',rows:[{label:'Bank cash before receipt',value:input.rrifKindBank},{label:'Cash portion received',value:r.cash},{label:'Tax cash earmark',value:-input.rrifKindTaxReserve},{label:'Planned household bills',value:-input.rrifKindSpend}],totalLabel:'Spare / unfunded budget capacity',note:'Bank cash before either assignment is paid equals CAD '+r.bankBalance.toLocaleString('en-CA',{maximumFractionDigits:2})+'. The tax reserve still belongs to the household and is not deducted from assets as though tax had already been remitted. The budget bridge deducts its availability once. Unsold securities contribute no bank cash here.'},
  {id:'rrif-kind-share-cash',type:'line',unit:'money',title:'Hold the gross payment fixed while changing its form',unitLabel:'CAD left after both cash assignments; negatives remain unfunded',xMin:0,xLabel:'Payment delivered as securities (%)',xUnit:'percent',xTicks:[0,.25,.5,.75,1].map(value=>({value,label:Math.round(value*100)+'%'})),series:[{name:'Cash budget remainder',rows:shares.map(share=>({x:share/100,value:rrifKindLedger(input,{rrifKindShare:share}).budget}))}],note:'Every point holds the represented gross payment, starting bank cash, tax earmark and bills unchanged. Only its form changes. More property can remain invested outside the RRIF while less bank cash arrives. This line is arithmetic across assumed mixes, not a forecast or proof the carrier offers every mix.'},
  {id:'rrif-kind-bank-matrix',type:'heatmap',unit:'money',title:'Compare starting bank cash with the securities share',unitLabel:'Additional CAD needed for the same two cash assignments',columns:matrixShares.map(s=>s+'%'),rows:bankAmounts.map(bank=>({label:'Cash $'+bank.toLocaleString('en-CA',{maximumFractionDigits:2}),values:matrixShares.map(share=>rrifKindLedger(input,{rrifKindBank:bank,rrifKindShare:share}).gap)})),note:'Columns replace the share delivered as securities; rows replace starting bank cash. All other values stay fixed. A zero cell means the two entered assignments are funded within this same-date illustration. It does not establish a lifetime reserve, a tax assessment, a preferable investment mix or the absence of later bills.'}
 ]};
}
